mapper.select:
SELECT null outTradeId, /*外部成交编号*/ deal.BOOKSET_ID finprodId,/**金融产品代码**/ bok.BOOKSET_NAME finprodName,/**金融产品名称**/ zc.FINPROD_MARKET_ID secId, /**资产代码**/ zc.FINPROD_ABBR secAbbr,/**资产简称**/ t.TRADE_MARKET tradeMarket,/**交易场所**/ t.PS ps,/**交易方向**/ t.TRADE_ID tradeId,/**交易编号**/ t.TRADE_DATE tradeDate,/**交易日**/ t.SETTLE_DATE settleDate,/**交割日期**/ stl.SETTLE_DATE fundSettleDate,/**资金交收日**/ t.INV_AIM invAim,/**会计分类**/ t.CHL_ID chlFinprodId,/**通道代码**/ t.SHARE_AMT tradeNum,/**成交数量**/ t.FPRICE_AMT fpriceAmt,/**全价总额**/ t.INT_AMT intAmt,/**应收利息总额**/ t.CCY ccy,/**币种**/ stl.SETTLE_AMT settleAmt,/**结算金额**/ t.TRADE_AMT bTradeAmt,/**本币交易金额**/ stl.MY_ACCT_NO acctNo/**资金账户**/ FROM TRD_PRODUCT_DEAL t LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_BOOKSET bok on bok.BOOKSET_ID = deal.BOOKSET_ID LEFT JOIN STL_ORDERS stl ON stl.TRADE_ID = t.TRADE_ID AND stl.BUSI_TYPE ='02' where t.BUSI_TYPE ='02'
and t.TRADE_ID like concat(concat('%',#{tradeId}),'%')
and deal.BOOKSET_ID IN
#{finprodId}
and zc.FINPROD_MARKET_ID IN
#{asset}
and t.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and t.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND t.PS IN
#{ps}
AND t.TRADE_MARKET IN
#{tradeMarket}
order by t.TRADE_ID desc

mapper.delete:
DELETE FROM BOK_DETAIL_ID
WHERE BOOKSET_ID = #{booksetId}
  and TRADE_ID = #{tradeId}

mapper.select:
SELECT A.FINPROD_ID id, NVL(A.FINPROD_ABBR, A.FINPROD_NAME) text FROM FIN_PRODUCT A WHERE A.IS_CHL = #{Y} AND A.FINPROD_TYPE2 = #{F28}
AND A.FINPROD_ID = #{initValue}
AND (A.FINPROD_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) )
